1	// T80: loaders for the landing page's "The result" section. Everything shown comes from the published report files:
2	// self/forward.json (the pre-registered forward test), self/review-1/decisions.json (v1) and
3	// self/review-1b/decision.json (the same tasks under the v2 gate). Each loader is pure over parsed JSON.
4	import { existsSync, readFileSync } from "node:fs";
5	import { join } from "node:path";
6	
7	export interface ForwardResult {
8	  wording: string;
9	  n: number;
10	  newOnly: number;
11	  oldOnly: number;
12	  both: number;
13	  neither: number;
14	  p: number;
15	}
16	
17	/** One gate call: the verdict string and the reasons exactly as the file gives them. */
18	export interface GateCall {
19	  verdict: string;
20	  reasons: string[];
21	  hiddenPass?: { incumbent: number; candidate: number };
22	}
23	
24	export interface Result {
25	  forward: ForwardResult | null;
26	  v1: GateCall | null;
27	  v2: GateCall | null;
28	}
29	
30	const DATA = join(process.cwd(), "public", "data");
31	
32	const object = (v: unknown): Record<string, unknown> | null =>
33	  typeof v === "object" && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : null;
34	const num = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
35	const strings = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);
36	
37	function forward(json: unknown): ForwardResult | null {
38	  const s = object(object(json)?.summary);
39	  if (!s || typeof s.wording !== "string") return null;
40	  const { n, newOnly, oldOnly, both, neither, p } = s;
41	  if (!num(n) || !num(newOnly) || !num(oldOnly) || !num(both) || !num(neither) || !num(p)) return null;
42	  return { wording: s.wording, n, newOnly, oldOnly, both, neither, p };
43	}
44	
45	function v1(json: unknown): GateCall | null {
46	  const root = object(json);
47	  const d = object(Array.isArray(root?.decisions) ? root.decisions[0] : null);
48	  if (!d || typeof d.verdict !== "string") return null;
49	  return { verdict: d.verdict, reasons: strings(d.reasons) };
50	}
51	
52	function v2(json: unknown): GateCall | null {
53	  const d = object(json);
54	  if (!d || typeof d.verdict !== "string") return null;
55	  const out: GateCall = { verdict: d.verdict, reasons: strings(d.reasons) };
56	  const h = object(d.hidden_pass);
57	  if (h && num(h.incumbent) && num(h.candidate)) out.hiddenPass = { incumbent: h.incumbent, candidate: h.candidate };
58	  return out;
59	}
60	
61	/** Builds the section's data from the three parsed files. Any missing or malformed file gives null for its part. */
62	export function loadResult(forwardJson: unknown, review1Json: unknown, review1bJson: unknown): Result {
63	  return { forward: forward(forwardJson), v1: v1(review1Json), v2: v2(review1bJson) };
64	}
65	
66	function readJson(file: string): unknown {
67	  if (!existsSync(file)) return undefined;
68	  try {
69	    return JSON.parse(readFileSync(file, "utf8"));
70	  } catch {
71	    return undefined;
72	  }
73	}
74	
75	/** The section's data from the files under dataDir (default public/data). */
76	export function loadResultFile(dataDir: string = DATA): Result {
77	  const self = join(dataDir, "self");
78	  return loadResult(
79	    readJson(join(self, "forward.json")),
80	    readJson(join(self, "review-1", "decisions.json")),
81	    readJson(join(self, "review-1b", "decision.json")),
82	  );
83	}
